record.field:
{
    "type": "object",
    "properties": {
        "name": {"type": "string", "description": "Título del evento"},
        "start": {"type": "string", "description": "Inicio en formato YYYY-MM-DD HH:MM (hora local de México)"},
        "duration_hours": {"type": "number", "description": "Duración en horas, 1 si no se dijo"},
        "attendee_names": {"type": "array", "items": {"type": "string"}, "description": "Nombres, tal como aparecen en la lista de personas conocidas, de asistentes además del responsable"},
        "description": {"type": "string"}
    },
    "required": ["name", "start"]
}

project = tools.find("project.project", project_name)
if not project and record.hub_task_id:
    project = record.hub_task_id.project_id
if not project:
    raise UserError("No se encontró el proyecto '%s'; indícalo en los argumentos." % (project_name or ""))
assignee = tools.find("res.users", assignee_name, [("share", "=", False)]) or record._tool_assignee()
vals = {
    "name": name,
    "project_id": project.id,
    "partner_id": record.partner_id.id,
    "description": description or "",
}
vals.update(record._tool_task_assignees(assignee))
if date_end:
    vals["date_end"] = tools.datetime(date_end, default_time="09:00", tz=record.user_id.tz or "America/Mexico_City")
if record.hub_task_id:
    vals["predecessor_ids"] = [(4, record.hub_task_id.id)]
task = env["project.task"].create(vals)
ai["result"] = {"model": "project.task", "id": task.id}

{
    "type": "object",
    "properties": {
        "name": {"type": "string", "description": "Título corto de la tarea"},
        "project_name": {"type": "string", "description": "Nombre del proyecto, vacío si no se sabe"},
        "assignee_name": {"type": "string", "description": "Persona responsable; vacío = responsable de la conversación"},
        "date_end": {"type": "string", "description": "Fecha límite YYYY-MM-DD, vacío si no se dijo"},
        "description": {"type": "string"}
    },
    "required": ["name"]
}

{
    "type": "object",
    "properties": {
        "summary": {"type": "string"},
        "date_deadline": {"type": "string", "description": "YYYY-MM-DD"},
        "note": {"type": "string"}
    },
    "required": ["summary", "date_deadline"]
}

if not record.partner_id:
    raise UserError("La conversación no tiene cliente.")
message = record.partner_id.message_post(body=body, subject="Nota desde conversación #%s" % record.id)
ai["result"] = {"model": "res.partner", "id": record.partner_id.id, "created": False}

{
    "type": "object",
    "properties": {"body": {"type": "string"}},
    "required": ["body"]
}

vals = {"name": name, "active": False, "description": description or ""}
category = tools.find("product.category", category_name)
if category:
    vals["categ_id"] = category.id
uom = tools.find("uom.uom", uom_name)
if uom:
    vals["uom_id"] = uom.id
if list_price:
    vals["list_price"] = list_price
template = env["product.template"].create(vals)
ai["result"] = {"model": "product.template", "id": template.id}

{
    "type": "object",
    "properties": {
        "name": {"type": "string", "description": "Nombre comercial con presentación, p. ej. 'Neonic XM 250 SC 20L'"},
        "category_name": {"type": "string"},
        "uom_name": {"type": "string", "description": "Unidad de medida: Litro, Kilo, Unidad"},
        "list_price": {"type": "number"},
        "description": {"type": "string"}
    },
    "required": ["name"]
}

env["ai.tool.model.access"]._check(model_name, "create")
created = env[model_name].create(tools.json(values_json))
ai["result"] = {"model": model_name, "id": created.id}

{
    "type": "object",
    "properties": {
        "model_name": {"type": "string", "description": "Nombre técnico del modelo, p. ej. crm.lead"},
        "values_json": {"type": "string", "description": "Objeto JSON con los valores por nombre técnico de campo"},
        "reason": {"type": "string"}
    },
    "required": ["model_name", "values_json", "reason"]
}

env["ai.tool.model.access"]._check(model_name, "write")
target = env[model_name].browse(res_id).exists()
if not target:
    raise UserError("No existe el registro %s #%s." % (model_name, res_id))
if not record._tool_can_update(target):
    raise UserError("Desde una conversación solo se actualiza su cliente o un registro creado desde ella.")
target.write(tools.json(values_json))
record._tool_note(target, "Actualizado desde conversación #%s: %s" % (record.id, reason))
ai["result"] = {"model": model_name, "id": target.id, "created": False}

{
    "type": "object",
    "properties": {
        "model_name": {"type": "string", "description": "Nombre técnico del modelo, p. ej. res.partner"},
        "res_id": {"type": "integer", "description": "Id del registro; para el cliente de la conversación usa su id del contexto"},
        "values_json": {"type": "string", "description": "Objeto JSON con los valores a escribir"},
        "reason": {"type": "string"}
    },
    "required": ["model_name", "res_id", "values_json", "reason"]
}

existing = env["res.partner"].search([("name", "=ilike", tools.like(name))], limit=1)
if not existing and phone:
    existing = env["res.partner"].search([("phone_ids.number", "=", phone)], limit=1)
if existing:
    raise UserError("Ya existe un contacto con ese nombre o teléfono: %s (id %s)." % (existing.display_name, existing.id))
vals = {"name": name, "is_company": bool(is_company), "email": email or False, "city": city or False, "comment": note or False}
if phone:
    vals["phone_ids"] = [(0, 0, {"number": phone, "type": "mobile", "primary": True})]
contact = env["res.partner"].create(vals)
if is_supplier and "supplier_rank" in contact._fields:
    contact.write({"supplier_rank": 1})
ai["result"] = {"model": "res.partner", "id": contact.id}

{
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "phone": {"type": "string"},
        "email": {"type": "string"},
        "city": {"type": "string"},
        "is_company": {"type": "boolean"},
        "is_supplier": {"type": "boolean", "description": "Verdadero si es proveedor"},
        "note": {"type": "string"}
    },
    "required": ["name"]
}
